// frontend/src/components/TaskManager/hooks/useTasks.ts

import { useState, useEffect } from 'react';
import axios from 'axios';
import { v4 as uuidv4 } from 'uuid'; 
import { Task } from '../types'; 

const API_URL = 'http://localhost:4000/api/tasks';

// Defines the shape of a new task object coming from the form
type NewTaskDetails = Omit<Task, 'id' | 'completed' | 'createdAt'>;

export const useTasks = () => {
    const [tasks, setTasks] = useState<Task[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [isServerOnline, setIsServerOnline] = useState(true);

    // Check if server is reachable
    const checkServerStatus = async () => {
        try {
            await axios.get(API_URL, { timeout: 5000 });
            setIsServerOnline(true);
            setError(null);
        } catch (error) {
            setIsServerOnline(false);
            console.warn('Backend server is not reachable. Using local state only.');
        }
    };

    // --- R (READ) LOGIC: Fetch tasks from the Express API ---
    useEffect(() => {
        const fetchTasks = async () => {
            await checkServerStatus();
            
            if (!isServerOnline) {
                // If server is offline, load from localStorage as fallback
                const savedTasks = localStorage.getItem('tasks');
                if (savedTasks) {
                    setTasks(JSON.parse(savedTasks));
                }
                setIsLoading(false);
                return;
            }

            try {
                // Axios GET request to the Backend API
                const response = await axios.get<Task[]>(API_URL, { timeout: 10000 });
                setTasks(response.data);
                // Also save to localStorage as backup
                localStorage.setItem('tasks', JSON.stringify(response.data));
                setError(null);
            } catch (error) {
                console.error("Error fetching tasks from API:", error);
                setError('Failed to load tasks from server. Using local data.');
                
                // Fallback to localStorage
                const savedTasks = localStorage.getItem('tasks');
                if (savedTasks) {
                    setTasks(JSON.parse(savedTasks));
                }
            } finally {
                setIsLoading(false);
            }
        };

        fetchTasks();
    }, []);

    // Save tasks to localStorage whenever they change
    useEffect(() => {
        if (tasks.length > 0) {
            localStorage.setItem('tasks', JSON.stringify(tasks));
        }
    }, [tasks]);

    // --- CRUD FUNCTIONS ---

    // C (CREATE): Add new task
    const addTask = async (taskDetails: NewTaskDetails) => {
        setIsLoading(true);
        setError(null);
        
        const newTask: Task = {
            ...taskDetails,
            id: uuidv4(), 
            completed: false,
            createdAt: new Date().toISOString(),
        };

        try {
            if (isServerOnline) {
                // Send POST request to API
                const response = await axios.post<Task>(API_URL, newTask, { timeout: 10000 });
                setTasks(prevTasks => [...prevTasks, response.data]);
                console.log("Task added successfully to API:", response.data);
            } else {
                // Local only
                setTasks(prevTasks => [...prevTasks, newTask]);
                console.log("Task added locally (server offline):", newTask);
            }
        } catch (error) {
            console.error("Error adding task to API:", error);
            setError('Failed to sync with server. Task saved locally.');
            // Fallback: add locally anyway
            setTasks(prevTasks => [...prevTasks, newTask]);
        } finally {
            setIsLoading(false);
        }
    };

    // U (UPDATE): Toggle task completion status
    const toggleComplete = async (id: string) => { 
        setIsLoading(true);
        setError(null);
        
        try {
            // Find the current task
            const taskToToggle = tasks.find(task => task.id === id);
            if (!taskToToggle) {
                throw new Error('Task not found');
            }

            const newCompletedState = !taskToToggle.completed;

            // Update local state immediately for better UX
            setTasks(prevTasks =>
                prevTasks.map(task =>
                    task.id === id ? { ...task, completed: newCompletedState } : task
                )
            );

            if (isServerOnline) {
                // Send PATCH request to API
                await axios.patch(`${API_URL}/${id}`, { 
                    completed: newCompletedState 
                }, { timeout: 10000 });
                console.log("Task completion synced with API");
            } else {
                console.log("Task completion updated locally (server offline)");
            }
        } catch (error) {
            console.error("Error toggling task completion:", error);
            setError('Failed to sync with server. Changes saved locally.');
            
            // Revert local state if API call fails (optional)
            // Or keep it as is since we updated optimistically
        } finally {
            setIsLoading(false);
        }
    };

    // U (UPDATE): Edit existing task
    const editTask = async (id: string, updates: Partial<Task>) => { 
        setIsLoading(true);
        setError(null);
        
        try {
            // Update local state immediately
            setTasks(prevTasks =>
                prevTasks.map(task =>
                    task.id === id ? { ...task, ...updates } : task
                )
            );

            if (isServerOnline) {
                // Send PATCH request to API
                const response = await axios.patch<Task>(`${API_URL}/${id}`, updates, { timeout: 10000 });
                console.log("Task updated successfully on API:", response.data);
            } else {
                console.log("Task updated locally (server offline)");
            }
        } catch (error) {
            console.error("Error updating task:", error);
            setError('Failed to sync with server. Changes saved locally.');
        } finally {
            setIsLoading(false);
        }
    };
    
    // D (DELETE): Remove task
    const deleteTask = async (id: string) => { 
        setIsLoading(true);
        setError(null);
        
        try {
            // Store the task for potential rollback
            const taskToDelete = tasks.find(task => task.id === id);
            
            // Update local state immediately
            setTasks(prevTasks => prevTasks.filter(task => task.id !== id));

            if (isServerOnline) {
                // Send DELETE request to API
                await axios.delete(`${API_URL}/${id}`, { timeout: 10000 });
                console.log("Task deleted successfully from API:", id);
            } else {
                console.log("Task deleted locally (server offline):", id);
            }
        } catch (error) {
            console.error("Error deleting task:", error);
            setError('Failed to sync with server. Changes saved locally.');
        } finally {
            setIsLoading(false);
        }
    };
    
    // Reorder tasks (local only for now)
    const reorderTasks = (newOrderedTasks: Task[]) => { 
        setTasks(newOrderedTasks); 
    };

    // Clear error message
    const clearError = () => setError(null);

    // Retry server connection
    const retryConnection = async () => {
        await checkServerStatus();
    };

    return {
        tasks,
        isLoading,
        error,
        isServerOnline,
        addTask,
        editTask,
        deleteTask,
        toggleComplete,
        reorderTasks,
        clearError,
        retryConnection,
    };
};